"""功能：生成包内可编辑的 SVG 原理插画，不使用真实数据冒充示意。
目的：让初学者看清对象、尺度和信息流；不重新绘制案例统计图。
输出：assets/illustrations/*.svg，与 content/illustrations.json 解释配套。
"""
from pathlib import Path
import json,html,math
ROOT=Path(__file__).resolve().parents[1]
E=lambda s:html.escape(str(s))
def text(x,y,s,size=18,color='#233f46',anchor='start'):
    return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" text-anchor="{anchor}">{E(s)}</text>'
def rect(x,y,w,h,fill='#e1eff4',rx=12):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="#6b9085"/>'
def circle(x,y,r,fill='#a9cbaa'):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" stroke="#547b70"/>'
def arrow(x,y,x2,y2):return f'<path d="M{x} {y}L{x2} {y2}" stroke="#557e65" stroke-width="2" fill="none" marker-end="url(#arrow)"/>'
def cell(x,y,color='#a9cbaa'):
    return circle(x,y,32,color)+circle(x-5,y-2,12,'#f7ecd0')+''.join(f'<path d="M{x+dx} {y+dy}q5-7 10 0" fill="none" stroke="#c87553" stroke-width="3"/>' for dx,dy in [(-15,18),(9,-14),(3,17)])
def grid(x,y,rows=4,cols=5,scale=26):
    return ''.join(rect(x+j*scale,y+i*scale,scale-2,scale-2,['#eaf2e5','#b1d1c7','#719e92','#3e7467'][(i*7+j*3)%4],2) for i in range(rows) for j in range(cols))
def scatter(x,y,color='#557e65',shift=0):
    return ''.join(circle(x+(i%7)*13+((i*11)%5),y+(i//7)*13+(i%3)*3+shift,3,color) for i in range(35))
def panel(x,y,title,lines,w=238):
    return rect(x,y,w,155,'#fff7df')+text(x+18,y+34,title,19)+''.join(text(x+18,y+65+27*i,l,15) for i,l in enumerate(lines))

