def main():
    directory=ROOT/'assets/illustrations';directory.mkdir(parents=True,exist_ok=True)
    meta={}
    for key,(title,summary,description,body) in art.items():
        meta[key]=dict(title=title,summary=summary,description=description)
        svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 850 420" role="img" aria-label="{E(title)}"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7Z" fill="#557e65"/></marker></defs><rect width="850" height="420" rx="18" fill="#f5f8ee"/><g font-family="Noto Sans CJK SC,Microsoft YaHei,sans-serif">{text(24,34,title,23)}{body}{text(24,404,"原理示意 · 数量、距离和颜色不代表本案例实际测量",13,"#547078")}</g></svg>'
        (directory/(key+'.svg')).write_text(svg)
    (ROOT/'content/illustrations.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':main()
